245: pub fn next_cap_reset(hint: &str, after: DateTime<Utc>) -> Option<DateTime<Utc>> {
246:     use chrono::{Datelike, Duration, FixedOffset, NaiveDate, NaiveTime, TimeZone, Weekday};
247:     // the grammar is ASCII; anything else is malformed (and never reaches a byte-offset split)
248:     if !hint.is_ascii() {
249:         return None;
250:     }
251:     let (kind, rest) = hint.split_once(':')?;
252:     // the clock and the offset: "HH:MM+08:00" (the last 6 characters are the offset)
253:     let split_clock = |s: &str| -> Option<(NaiveTime, FixedOffset)> {
254:         if !s.is_ascii() || s.len() < 11 {
255:             return None;
256:         }
257:         let (clock, off) = s.split_at(s.len() - 6);
258:         let t = NaiveTime::parse_from_str(clock, "%H:%M").ok()?;
259:         let sign = match off.as_bytes()[0] {
260:             b'+' => 1,
261:             b'-' => -1,
262:             _ => return None,
263:         };
264:         let (oh, om) = off[1..].split_once(':')?;
265:         let secs = sign * (oh.parse::<i32>().ok()? * 3600 + om.parse::<i32>().ok()? * 60);
266:         Some((t, FixedOffset::east_opt(secs)?))
267:     };
