269:         "monthly" => {
270:             let (day, clock) = rest.split_once('T')?;
271:             let day: u32 = day.parse().ok().filter(|d| (1..=31).contains(d))?;
272:             let (t, off) = split_clock(clock)?;
273:             let local = after.with_timezone(&off);
274:             let (mut y, mut m) = (local.year(), local.month());
275:             for _ in 0..14 {
